style.css:
/* Apply a grayscale filter to desaturate the page */
html {
    filter: grayscale(100%);
}

/* Apply an invert filter to invert the colors */
html {
    filter: grayscale(100%) invert(100%);
}

/* Apply a contrast filter to enhance the edge effect */
html {
    filter: grayscale(100%) invert(100%) contrast(200%);
}

/* Apply a brightness filter to adjust the overall brightness */
html {
    filter: grayscale(100%) invert(100%) contrast(200%) brightness(150%);
}

/* Combine all filters */
html {
    filter: grayscale(100%) invert(100%) contrast(200%) brightness(150%);
}
